  );

  if (commandWasCaptured) {
    await closeOpenModals(page);
    await page.evaluate((): void => {
      const dgWindow = window as unknown as DgPlaywrightWindow;
      const openSettings =
        dgWindow.__dgPlaywrightCommandCallbacks?.[
          "DG: Open - Discourse settings"
        ];
