    // Lay the fixtures out in a row so each has its own hit area.
    const ids = await page.evaluate(
      ({ title, fixtures }) => {
        const editor = window.tldrawApps[title];
        editor.selectAll().deleteShapes(editor.getSelectedShapeIds());
        const made = {};
        fixtures.forEach((f, i) => {
          const id = `shape:eng1884_${f.key.replace(/-/g, "_")}`;
          const x = 100 + i * 260;
          const base = { id, type: f.type, x, y: 200 };
          if (f.type === "arrow") {
            editor.createShapes([{ ...base, props: { text: f.text, start: { x: 0, y: 0 }, end: { x: 160, y: 0 } } }]);
          } else if (f.type === "geo") {
