      allowCredentialLogin: resolvedAllowCredentialLogin,
      timeout,
    });
  } catch (error) {
    await closeRoamSession({ context });
    throw error;
  }

  return {
    context,
    page,
    slotConfig: resolvedConfig,
    headless: resolvedHeadless,
    close: () => closeRoamSession({ context }),
  };
};
