// Glide the drawn cursor to a point, capturing frames, then put the real mouse there.
const moveTo = async (page, x, y, ms = 500) => {
  const steps = Math.max(2, Math.round((ms / 1000) * FPS));
  const from = (await page.evaluate(() => {
    const c = document.getElementById("dg-demo-cursor");
    return c ? [parseFloat(c.style.left) || 0, parseFloat(c.style.top) || 0] : [0, 0];
  }));
  for (let i = 1; i <= steps; i += 1) {
    const t = i / steps;
    const ease = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    const cx = from[0] + (x - from[0]) * ease;
    const cy = from[1] + (y - from[1]) * ease;
    await page.evaluate(([px, py]) => window.__dgCursor(px, py), [cx, cy]);
    await page.mouse.move(cx, cy);
    await shoot(page);
  }
  await page.mouse.move(x, y);
};

const closeDialogs = async (page) => {
  for (let i = 0; i < 4; i += 1) {
    if (!(await page.evaluate(() => Boolean(document.querySelector(".bp3-dialog, .bp3-overlay-open"))))) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(400);
  }
};

const waitFor = async (page, fn, t = 60000, l = "condition") => {
  const s = Date.now();
  for (;;) {
    if (await page.evaluate(fn)) return;
    if (Date.now() - s > t) throw new Error(`timeout waiting for ${l}`);
    await page.waitForTimeout(250);
  }
};

const screenPointOf = (page, id) =>
